class Animal {
    protected String name; // protected: visible to Animal and any subclass

    public Animal(String name) {
        this.name = name;
    }

    public void eat() {
        System.out.println(name + " is eating");
    }

    public void makeSound() {
        System.out.println(name + " makes a generic animal sound");
    }
}

// Dog IS-A Animal: it inherits everything Animal has, and can add or override
class Dog extends Animal {
    public Dog(String name) {
        super(name); // must call the parent constructor first
    }

    @Override
    public void makeSound() { // overriding: Dog has its own specific sound
        System.out.println(name + " barks: Woof!");
    }

    public void fetch() { // Dog-specific behavior, Animal knows nothing about this
        System.out.println(name + " fetches the ball");
    }
}

public class Main {
    public static void main(String[] args) {
        Dog dog = new Dog("Rex");

        dog.eat();       // inherited directly from Animal, no need to rewrite it
        dog.makeSound(); // Dog's own overridden version runs, not Animal's
        dog.fetch();     // Dog-only behavior
    }
}

