#include <iostream>
#include <string>
using namespace std;

class Animal {
protected:
    string name; // protected: visible to Animal and any subclass

public:
    Animal(string name) : name(name) {}

    void eat() {
        cout << name << " is eating" << endl;
    }

    virtual void makeSound() { // virtual so Dog is allowed to override it
        cout << name << " makes a generic animal sound" << endl;
    }
};

// Dog IS-A Animal: it inherits everything Animal has, and can add or override
class Dog : public Animal {
public:
    Dog(string name) : Animal(name) {} // must call the parent constructor first

    void makeSound() override { // overriding: Dog has its own specific sound
        cout << name << " barks: Woof!" << endl;
    }

    void fetch() { // Dog-specific behavior, Animal knows nothing about this
        cout << name << " fetches the ball" << endl;
    }
};

int main() {
    Dog dog("Rex");

    dog.eat();       // inherited directly from Animal, no need to rewrite it
    dog.makeSound(); // Dog's own overridden version runs, not Animal's
    dog.fetch();     // Dog-only behavior

    return 0;
}
